mapper.select:
SELECT pl.like_id AS likeId, u.user_id AS userId, u.nickname AS nickname, u.profile_image_url AS profileImageUrl FROM post_likes pl JOIN users u ON u.user_id = pl.user_id WHERE pl.post_id = #{postId}
AND pl.like_id < #{cursor}
ORDER BY pl.like_id DESC LIMIT #{limit}

SELECT pl.like_id AS likeId, p.post_id AS postId, p.post_type AS postType, p.content AS content,
COALESCE( p.thumbnail_url, (SELECT m.media_url FROM post_medias m WHERE m.post_id = p.post_id AND m.media_type = 'IMAGE' ORDER BY m.display_order, m.media_id LIMIT 1) ) AS thumbnailUrl,
(SELECT COUNT(*) FROM post_likes c WHERE c.post_id = p.post_id) AS likeCount, p.comment_count AS commentCount, u.user_id AS authorId, u.nickname AS authorNickname, u.profile_image_url AS authorProfileImageUrl, pl.created_at AS likedAt, p.created_at AS postCreatedAt FROM post_likes pl JOIN posts p ON p.post_id = pl.post_id JOIN users u ON u.user_id = p.user_id WHERE pl.user_id = #{userId}
AND pl.like_id < #{cursor}
ORDER BY pl.like_id DESC LIMIT #{limit}
